import{_ as r}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/BDM.scaBLLhv.js";import{_ as t,a as n,b as s,c as i,d as o}from"./chunks/M-SS-LimiTTer.Bke--kwa.js";import{_ as l,o as p,c as u,a3 as c}from"./chunks/framework.g9mfNVRQ.js";const q=JSON.parse('{"title":"Démarrer le capteur","description":"","frontmatter":{"source_hash":"ec23b1baed","source_commit":"ea9ce3a","i18n_outdated":true},"headers":[],"relativePath":"fr/use/startsensor.md","filePath":"fr/use/startsensor.md"}'),d={name:"fr/use/startsensor.md"};function m(v,e,g,b,f,h){return p(),u("div",null,[...e[0]||(e[0]=[c('<p>Démarrer un capteur dans xDrip a des fonctions très différentes selon le capteur.</p><h3 id="g6-and-1" tabindex="-1">G6 et 1 <a class="header-anchor" href="#g6-and-1" aria-label="Permalink to &quot;G6 et 1 {#g6-and-1}&quot;">​</a></h3><p>La documentation de référence se trouve <a href="https://navid200.github.io/xDrip/docs/Proper-connectivity.html" target="_blank" rel="noreferrer">ici</a>.</p><h3 id="g7-and-1" tabindex="-1">G7 et 1+ <a class="header-anchor" href="#g7-and-1" aria-label="Permalink to &quot;G7 et 1+ {#g7-and-1}&quot;">​</a></h3><p>Le capteur démarre automatiquement au moment de son insertion. Vous n&#39;avez pas besoin de le démarrer dans xDrip.</p><br><h3 id="libre" tabindex="-1">Libre <a class="header-anchor" href="#libre" aria-label="Permalink to &quot;Libre {#libre}&quot;">​</a></h3><p>Remarque : cette section ne s&#39;applique PAS au Libre 2/2+ (UE) connecté à xDrip sans transmetteur. Pour ceux-ci, consultez les instructions <a href="./../install/libre2.html#starting-libre-2-sensors">Libre 2 Direct</a></p><p>xDrip ne peut pas démarrer un capteur Libre, ni l&#39;arrêter (en fait, ce capteur ne peut pas être arrêté : s&#39;il ne tombe pas en panne, il fonctionne pendant toute sa durée de vie et s&#39;arrête de lui-même au bout de 14 jours et 12 heures ; les capteurs Libre 3 fonctionnent 15 jours).</p><p>Pour démarrer votre capteur, vous devez utiliser le lecteur ou l&#39;application du fabricant ; certaines applications tierces comme Glimp-S et eDropletNFC peuvent démarrer le capteur Libre 1. Juggluco peut démarrer les capteurs Libre 2 et 3.</p><p>Le démarrage du capteur dans xDrip sert uniquement à suivre sa durée de vie et à garantir la mise à jour des étalonnages. Cette opération est nécessaire et recommandée à chaque remplacement du capteur.</p><br><div class="admonition xdrip"><p class="admonition-title"><img src="'+r+'" style="zoom:75%;"></p><p> Démarrer le capteur</p></div><p>Confirmez avec DÉMARRER LE CAPTEUR</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;">Démarrer un nouveau capteur</p><p>Ne pas cliquer sur &#39;démarrer le capteur&#39; à moins que le capteur ne soit déjà installé et l&#39;émetteur connecté.</p><p>    <span style="background-color:grey;color:white;align:center;">  DÉMARRER LE CAPTEUR </span></p></div><p>Si vous avez inséré le capteur aujourd&#39;hui (c&#39;est-à-dire non démarré ou démarré récemment), répondez OUI, AUJOURD&#39;HUI</p><div class="admonition xdripitem"><p class="admonition-title">L&#39;avez-vous installé aujourd&#39;hui ?</p><p>Nous devons savoir quand le capteur a été installé pour améliorer la précision de calcul.</p><p><span style="color:cyan;float:right;">PAS AUJOURD&#39;HUI  OUI, AUJOURD&#39;HUI </span></p></div><p>Si vous avez répondu aujourd&#39;hui, sélectionnez l&#39;heure à laquelle vous avez physiquement démarré le capteur en faisant glisser l&#39;aiguille bleue sur la bonne heure. En affichage 12 heures, appuyez sur <code>am</code> ou<code>pm</code>. En affichage 24 heures, déposez l&#39;aiguille sur le cercle intérieur ou extérieur, selon l&#39;heure. Appuyez sur OK.</p><img src="'+t+'" style="zoom:75%;"><p>Faites glisser l&#39;aiguille bleue des minutes sur la bonne valeur et appuyez sur <code>OK</code>.</p><img src="'+n+'" style="zoom:75%;"><p>Le capteur nouvellement démarré poursuivra son préchauffage s&#39;il a été démarré il y a moins d&#39;une heure.</p><div class="warning custom-block"><p class="custom-block-title">Attention</p><p><strong>Même si xDrip essaie de lire un capteur pendant sa phase de préchauffage, les valeurs peuvent être peu fiables, voire incohérentes, et ne doivent pas être utilisées.</strong></p></div><img src="'+s+'" style="zoom:70%;"><p>Si vous utilisez <a href="./OOP.html#oop1">OOP1</a> ou <a href="./OOP.html#oop2">OOP2</a> sans étalonnage, la glycémie s&#39;affichera immédiatement, sans étalonnage initial.</p><p>Si vous utilisez un capteur déjà démarré, une demande d&#39;étalonnage apparaîtra dans les 15 minutes.</p><p>Si vous voyez une flèche violette, vous vous êtes peut-être trompé dans la date et l&#39;heure de démarrage du capteur : des données de glycémie sont disponibles mais ne s&#39;afficheront pas pendant le préchauffage d&#39;une heure.</p><img src="'+i+'" style="zoom:70%;"><br><p>xDrip va maintenant attendre les valeurs et afficher la progression. Restez sur cet écran. Les valeurs arrivent toutes les 5 minutes, cela devrait donc prendre moins de 20 minutes.</p><div class="admonition xdripitem"><p class="admonition-title">Collecte des premières lectures</p><p> ✔ Collecteur de données en cours d&#39;exécution<br>  ⧖ Réception des données du Collecteur MiaoMiao<br>   Reçu quelques données récentes<br>   Reçu assez de bonnes données pour calibrer<br>  <em><strong>No data received yet</strong></em></p></div><p>Si la source de données indique LimiTTer alors que vous n&#39;utilisez pas un vrai <a href="https://github.com/JoernL/LimiTTer" target="_blank" rel="noreferrer">LimiTTer</a>, votre transmetteur n&#39;est pas correctement connecté.</p><img src="'+o+'" style="zoom:70%;"><p>L&#39;indication <em><strong>No data received yet</strong></em> deviendra <em><strong>Need 3 recent readings</strong></em>. Si aucune donnée n&#39;est reçue, <a href="./../install/libreBT.html#bridge-settings">vérifiez vos paramètres</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Collecte des premières lectures</p><p> ✔ Collecteur de données en cours d&#39;exécution<br>  ✔ Réception des données du Collecteur MiaoMiao<br>  ✔ Reçu quelques données récentes<br>  ⧖ Reçu assez de bonnes données pour calibrer<br>  <em><strong>Need 3 recent readings, got only 1 so far</strong></em><br>  Next reading expected in 1 minute</p></div><p>Lorsque suffisamment de valeurs ont été reçues, la demande d&#39;étalonnage s&#39;affiche. En savoir plus sur l&#39;étalonnage <a href="./../calibrate/101.html">ici</a>.</p><p>Si votre glycémie est dans la plage normale (de préférence dans le bas de la plage normale pour un nouveau capteur) et stable depuis 10 minutes, sans glucides ni insuline actifs, vous pouvez étalonner.</p><p>Si votre glycémie varie rapidement ou n&#39;est pas dans la plage normale, il est déconseillé d&#39;étalonner maintenant.</p><div class="admonition xdrip"><p class="admonition-title">Calibrer le capteur?</p><p>Nous avons quelques valeurs!<br> Ensuite, nous avons besoin d&#39;un premier test de glycémie capillaire.<br> Prêt à calibrer maintenant ?</p></div><p>Deux valeurs peuvent être demandées pour le premier étalonnage ; vous pouvez n&#39;en utiliser qu&#39;une si vous êtes sûr qu&#39;elle est valide : saisissez simplement deux fois la même valeur. Vous pouvez définir une seule valeur par défaut en <a href="./../calibrate/advancedcal.html#calibrations">désactivant le double étalonnage</a>.</p><p>Votre glycémie devrait commencer à s&#39;afficher sur le graphique principal.</p><br><h3 id="followers-and-companion-apps" tabindex="-1">Abonnés et applications compagnon <a class="header-anchor" href="#followers-and-companion-apps" aria-label="Permalink to &quot;Abonnés et applications compagnon {#followers-and-companion-apps}&quot;">​</a></h3><p>Il est parfois nécessaire de « démarrer » une session de capteur dans xDrip pour obtenir des valeurs.</p><p>Démarrer ou arrêter un capteur dans xDrip, avec une source abonné ou application compagnon, n&#39;a aucun effet sur le capteur.</p><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>La seule exception est <a href="./sync.html#accept-followers-actions">l&#39;abonné xDrip Sync, qui peut transmettre la commande de démarrage ou d&#39;arrêt au capteur s&#39;il est directement connecté au xDrip principal</a>.<br> N&#39;utilisez pas Démarrer et Arrêter le capteur avec un abonné xDrip Sync, à moins d&#39;être sûr que la personne qui a le téléphone xDrip principal saura quoi faire d&#39;un capteur arrêté !</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+r+'" style="zoom:75%;"></p><p> Démarrer le capteur</p></div><p>Confirmez avec DÉMARRER LE CAPTEUR</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;">Démarrer un nouveau capteur</p><p>Ne pas cliquer sur &#39;démarrer le capteur&#39; à moins que le capteur ne soit déjà installé et l&#39;émetteur connecté.</p><p>    <span style="background-color:grey;color:white;align:center;">  DÉMARRER LE CAPTEUR </span></p></div><p>Répondez PAS AUJOURD&#39;HUI</p><div class="admonition xdripitem"><p class="admonition-title">L&#39;avez-vous installé aujourd&#39;hui ?</p><p>Nous devons savoir quand le capteur a été installé pour améliorer la précision de calcul.</p><p><span style="color:cyan;float:right;">PAS AUJOURD&#39;HUI  OUI, AUJOURD&#39;HUI </span></p></div><p>xDrip devrait récupérer les valeurs à la prochaine mesure.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',54)])])}const y=l(d,[["render",m]]);export{q as __pageData,y as default};
